let n := 42;
if (n > 0) {
    println("positive");
} else {
    println("non-positive");
}

let i := 0;
while (i < 5) {
    println(i);
    i := i + 1;
}

for (let i := 0; i < 10; i := i + 1) {
    println(i);
}

for (let i := 1; i <= 5; i := i + 1) {
    let doubled := i * 2;
    println(doubled);
}

let score := 65;
if (score < 40) {
    println("low");
} else {
    if (score < 70) {
        println("medium");
    } else {
        println("high");
    }
}

func add(a, b) {
    return a + b;
}

